using System.Net;
using System.Text;
using SalekhPos.Desktop.Infrastructure.Management;
using Xunit;
namespace SalekhPos.Desktop.Tests; public sealed class FeatureManagerHttpTests { [Fact] public async Task EvaluatesFeatureWithOrganizationScope() { var org = Guid.NewGuid(); string? path = null; using var c = Client(r => { path = r.RequestUri!.PathAndQuery; return Json("""{"key":"pos.core","enabled":true,"source":"policy","evaluatedAt":"2026-09-18T08:00:00Z"}"""); }); var v = await new HttpFeatureManager(c).EvaluateAsync(org, "pos.core", default); Assert.True(v.Enabled); Assert.Equal($"/api/v1/organizations/{org:D}/features/pos.core", path); } private static HttpClient Client(Func<HttpRequestMessage, HttpResponseMessage> f) => new(new H(f)) { BaseAddress = new("https://pos.test/") }; private static HttpResponseMessage Json(string x) => new(HttpStatusCode.OK) { Content = new StringContent(x, Encoding.UTF8, "application/json") }; private sealed class H(Func<HttpRequestMessage, HttpResponseMessage> f) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r, CancellationToken ct) => Task.FromResult(f(r)); } }
